//! `sermofur_core::challenge` against the scenarios that the .NET `ChallengeService` answered on
//! the real `SqliteStore` (`rust/tests/golden/challenge.json`, regenerated by
//! `rust/tools/challenge-oracle`): each scenario is replayed in a new instance, and every answer
//! is compared with the JSON text the oracle wrote, line breaks as `\n`.
//!
//! The close claims reuse the excerpt of `recall` (named deviation A4 of `PARITY.md`). No
//! challenged text is long enough to cut an excerpt, so no case is listed: any difference fails.

use std::collections::HashSet;
use std::path::{Path, PathBuf};

use proptest::prelude::*;
use serde_json::{Value, json};
use sermofur_core::challenge::{challenge_claim, challenge_text};
use sermofur_core::format::DateTimeOffset;
use sermofur_core::memory::MemoryContext;
use sermofur_core::records::*;
use sermofur_core::store::Store;
use uuid::Uuid;

/// The temporary directory as the oracle's `TestInstance.TempRoot` sees it: links resolved, since
/// on macOS `/var` is a link to `/private/var` and the store refuses links on every ancestor.
/// Windows keeps `temp_dir` as is (`canonicalize` would add the `\\?\` prefix).
fn temp_base() -> PathBuf {
    let dir = std::env::temp_dir();
    if cfg!(windows) {
        dir
    } else {
        std::fs::canonicalize(dir).expect("the temporary directory resolves")
    }
}

struct Scratch(PathBuf);

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn instance() -> (Scratch, Store) {
    let scratch =
        Scratch(temp_base().join(format!("sermofur-challenge-{}", Uuid::new_v4().simple())));
    std::fs::create_dir_all(scratch.0.join(".sermofur")).expect("marker");
    let id = Uuid::parse_str("11111111-2222-4333-8444-555555555555").expect("GUID");
    sermofur_core::schema::create_database(&scratch.0.join(".sermofur").join("memory.db"), id)
        .expect("created");
    let store = Store::open(&scratch.0, id, false).expect("opened");
    (scratch, store)
}

fn context(root: &Path, scope: &str) -> MemoryContext {
    MemoryContext {
        root: root.to_path_buf(),
        scope_id: scope.to_owned(),
        visible: HashSet::new(),
    }
}

fn text(value: &Value) -> &str {
    value.as_str().expect("string")
}

/// An answer as the oracle recorded it: the JSON text, or the refusal.
fn answer<T: serde::Serialize>(result: sermofur_core::error::Result<T>) -> Value {
    match result {
        Ok(value) => Value::String(
            sermofur_core::json::to_string(&value)
                .expect("JSON")
                .replace("\r\n", "\n"),
        ),
        Err(error) => json!({
            "code": error.code,
            "message": error.message,
            "exitCode": error.exit_code,
        }),
    }
}

#[test]
fn challenge_answers_like_the_dotnet_service() {
    let path = format!(
        "{}/../../tests/golden/challenge.json",
        env!("CARGO_MANIFEST_DIR")
    );
    let golden: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("golden file")).expect("JSON");
    let mut mismatches = Vec::new();
    let mut challenges = 0;
    for scenario in golden["scenarios"].as_array().expect("scenarios") {
        let name = text(&scenario["name"]);
        let (scratch, mut store) = instance();
        for step in scenario["steps"].as_array().expect("steps") {
            match text(&step["op"]) {
                "addScope" => {
                    let kind = ScopeKind::NAMES
                        .iter()
                        .find(|(n, _, _)| *n == text(&step["kind"]))
                        .map(|(_, _, m)| *m)
                        .expect("scope kind");
                    let scope = Scope {
                        id: text(&step["id"]).to_owned(),
                        kind,
                        parent_id: Some(text(&step["parent"]).to_owned()),
                        relative_path: Some(text(&step["path"]).to_owned()),
                    };
                    store.add_scope(&scope, |_| Ok(())).expect("scope added");
                }
                "create" => {
                    let record: MemoryRecord =
                        read(text(&step["payload"]), &|_| 0).expect("payload");
                    store.create_record(&record, None).expect("created");
                }
                "invalidate" => {
                    let id = Uuid::parse_str(text(&step["id"])).expect("GUID");
                    store
                        .invalidate_record(id, text(&step["scope"]), text(&step["reason"]), "john")
                        .expect("invalidated");
                }
                op @ ("challenge" | "challengeText") => {
                    challenges += 1;
                    let context = context(&scratch.0, text(&step["scope"]));
                    let now = DateTimeOffset::now_utc();
                    let (actual, label) = if op == "challenge" {
                        let id = Uuid::parse_str(text(&step["id"])).expect("GUID");
                        (
                            answer(challenge_claim(&store, &context, id, now)),
                            text(&step["id"]).to_owned(),
                        )
                    } else {
                        let question = text(&step["text"]);
                        (
                            answer(challenge_text(&store, &context, question, now)),
                            question.chars().take(40).collect(),
                        )
                    };
                    if actual != step["answer"] {
                        mismatches.push(format!(
                            "{name} {op} {label:?}:\n  expected {}\n  got      {}",
                            step["answer"], actual
                        ));
                    }
                }
                other => panic!("unknown step {other}"),
            }
        }
    }
    eprintln!("challenge: {challenges} challenges compared");
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(128))]

    /// Any text is either refused as `invalid_input` (blank, NUL, beyond bounds, or without a
    /// searchable term) or challenged as itself, without signals, with at most 3 claims to
    /// confront that never include a non-applicable one; nothing panics.
    #[test]
    fn any_text_is_refused_or_challenged_as_itself(
        candidate in prop::collection::vec(
            prop::sample::select(vec![
                "cache", " ", "\t", "\0", "!", "\"", "*", "é", "🙂", "OR", "NEAR(", "\u{0301}",
                "\u{FFFD}", "redis",
            ]),
            0..12,
        ),
    ) {
        let (scratch, mut store) = instance();
        let user = Provenance {
            origin: ActorKind::User,
            actor: Some("john".to_owned()),
            timestamp: DateTimeOffset::now_utc(),
        };
        for (n, status) in [KnowledgeStatus::Proposed, KnowledgeStatus::Invalidated]
            .into_iter()
            .enumerate()
        {
            let claim = ClaimContent {
                text: Some(format!("cache redis {n}")),
                category: MemoryCategory::Semantic,
                volatility: Volatility::Stable,
                last_verified: None,
                review_after: None,
            };
            let record = MemoryRecord {
                id: Uuid::new_v4(),
                scope_id: Some("workspace".to_owned()),
                kind: RecordKind::Claim,
                status,
                revision: 1,
                content_json: Some(write(&claim).expect("JSON")),
                provenance: Some(user.clone()),
            };
            store.create_record(&record, None).expect("created");
        }
        let candidate: String = candidate.concat();
        let context = context(&scratch.0, "workspace");
        match challenge_text(&store, &context, &candidate, DateTimeOffset::now_utc()) {
            Ok(answer) => {
                prop_assert_eq!(&answer.target.text, &candidate);
                prop_assert!(answer.target.claim_id.is_none() && answer.target.status.is_none());
                prop_assert!(answer.signals.is_empty());
                prop_assert!(answer.to_confront.len() <= 1);
                prop_assert!(answer.to_confront.iter().all(|r| r.applicable && r.kind == "claim"));
            }
            Err(error) => prop_assert_eq!(error.code, "invalid_input"),
        }
    }
}
